use anyhow::Result;
use clap::Parser;
use crossterm::{
    event::{self, DisableMouseCapture, EnableMouseCapture, Event, KeyCode},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::{
    backend::{Backend, CrosstermBackend},
    layout::{Constraint, Direction, Layout, Rect},
    widgets::{Block, Borders, Tabs, Paragraph},
    Frame, Terminal,
};
use std::io;
use std::path::PathBuf;

#[derive(Parser)]
#[command(author, version, about, long_about = None)]
struct Args {
    #[arg(help = "Path to the parquet file")]
    path: PathBuf,
}

enum Tab {
    Visualize,
    Metadata,
    Schema,
    RowGroups,
}

impl Tab {
    fn from_index(index: usize) -> Self {
        match index {
            0 => Tab::Visualize,
            1 => Tab::Metadata,
            2 => Tab::Schema,
            3 => Tab::RowGroups,
            _ => Tab::Visualize,
        }
    }

    fn to_index(&self) -> usize {
        match self {
            Tab::Visualize => 0,
            Tab::Metadata => 1,
            Tab::Schema => 2,
            Tab::RowGroups => 3,
        }
    }

    fn names() -> Vec<&'static str> {
        vec!["Visualize", "Metadata", "Schema", "Row Groups"]
    }
}

struct App {
    path: PathBuf,
    active_tab: Tab,
    should_quit: bool,
}

impl App {
    fn new(path: PathBuf) -> Self {
        Self {
            path,
            active_tab: Tab::Visualize,
            should_quit: false,
        }
    }

    fn next_tab(&mut self) {
        let current_index = self.active_tab.to_index();
        self.active_tab = Tab::from_index((current_index + 1) % 4);
    }
}

fn main() -> Result<()> {
    let args = Args::parse();

    // setup terminal
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen, EnableMouseCapture)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    // create app and run it
    let mut app = App::new(args.path);
    let res = run_app(&mut terminal, &mut app);

    // restore terminal
    disable_raw_mode()?;
    execute!(
        terminal.backend_mut(),
        LeaveAlternateScreen,
        DisableMouseCapture
    )?;
    terminal.show_cursor()?;

    if let Err(err) = res {
        println!("{:?}", err)
    }

    Ok(())
}

fn run_app<B: Backend>(terminal: &mut Terminal<B>, app: &mut App) -> io::Result<()> {
    while !app.should_quit {
        terminal.draw(|f| ui(f, app))?;

        if event::poll(std::time::Duration::from_millis(100))? {
            if let Event::Key(key) = event::read()? {
                match key.code {
                    KeyCode::Char('q') | KeyCode::Char('Q') => app.should_quit = true,
                    KeyCode::Tab => app.next_tab(),
                    _ => {}
                }
            }
        }
    }
    Ok(())
}

fn ui(f: &mut Frame, app: &App) {
    let size = f.size();
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(3),
            Constraint::Min(0),
            Constraint::Length(1),
        ])
        .split(size);

    let titles = Tab::names();
    let tabs = Tabs::new(titles)
        .block(Block::default().borders(Borders::ALL))
        .select(app.active_tab.to_index())
        .highlight_style(ratatui::style::Style::default().add_modifier(ratatui::style::Modifier::REVERSED));

    // In the actual app, the tab bar has the filename on the right.
    // We can use a custom widget or just draw it on top of the block.
    f.render_widget(tabs, chunks[0]);

    let path_str = app.path.to_string_lossy();
    let path_para = Paragraph::new(path_str.as_ref())
        .alignment(ratatui::layout::Alignment::Right)
        .block(Block::default());

    // Draw path on the right side of the tab bar
    let tab_inner = chunks[0].inner(&ratatui::layout::Margin { vertical: 1, horizontal: 1 });
    f.render_widget(path_para, tab_inner);

    let content = match app.active_tab {
        Tab::Visualize => Paragraph::new("Visualize Content"),
        Tab::Metadata => Paragraph::new("Metadata Content"),
        Tab::Schema => Paragraph::new("Schema Content"),
        Tab::RowGroups => Paragraph::new("Row Groups Content"),
    };
    f.render_widget(content, chunks[1]);

    let footer = Paragraph::new("parqeye           [Tab] Next Tab, [Q]uit");
    f.render_widget(footer, chunks[2]);
}
EOF
"}

