{"command":"cat <<'EOF' > src/main.rs
use anyhow::Result;
use clap::Parser;
use crossterm::{
    event::{self, DisableMouseCapture, EnableMouseCapture, Event, KeyCode},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::{
    backend::{Backend, CrosstermBackend},
    layout::{Constraint, Direction, Layout, Rect, Alignment},
    widgets::{Block, Borders, Tabs, Paragraph, Row, Table, Cell},
    style::{Color, Modifier, Style},
    Frame, Terminal,
};
use std::io;
use std::path::{Path, PathBuf};
use std::fs::File;
use parquet::file::reader::{FileReader, SerializedFileReader};
use parquet::schema::types::Type;
use std::sync::Arc;

#[derive(Parser)]
#[command(author, version, about, long_about = None)]
struct Args {
    #[arg(help = "Path to the parquet file")]
    path: PathBuf,
}

#[derive(Clone, Copy, PartialEq)]
enum Tab {
    Visualize,
    Metadata,
    Schema,
    RowGroups,
}

impl Tab {
    fn from_index(index: usize) -> Self {
        match index {
            0 => Tab::Visualize,
            1 => Tab::Metadata,
            2 => Tab::Schema,
            3 => Tab::RowGroups,
            _ => Tab::Visualize,
        }
    }

    fn to_index(&self) -> usize {
        match self {
            Tab::Visualize => 0,
            Tab::Metadata => 1,
            Tab::Schema => 2,
            Tab::RowGroups => 3,
        }
    }

    fn names() -> Vec<&'static str> {
        vec!["Visualize", "Metadata", "Schema", "Row Groups"]
    }
}

struct App {
    path: PathBuf,
    active_tab: Tab,
    should_quit: bool,

    // Parquet data
    file_reader: Arc<SerializedFileReader<File>>,
    num_rows: usize,
    num_cols: usize,
    num_row_groups: usize,

    // Visualize state
    row_offset: usize,
    col_offset: usize,
    selected_row: usize,
}

impl App {
    fn new(path: PathBuf) -> Result<Self> {
        let file = File::open(&path)?;
        let file_reader = Arc::new(SerializedFileReader::new(file)?);
        let metadata = file_reader.metadata();
        let num_rows = metadata.file_metadata().num_rows() as usize;
        let num_cols = metadata.file_metadata().schema().num_columns();
        let num_row_groups = metadata.num_row_groups();

        Ok(Self {
            path,
            active_tab: Tab::Visualize,
            should_quit: false,
            file_reader,
            num_rows,
            num_cols,
            num_row_groups,
            row_offset: 0,
            col_offset: 0,
            selected_row: 0,
        })
    }

    fn next_tab(&mut self) {
        let current_index = self.active_tab.to_index();
        self.active_tab = Tab::from_index((current_index + 1) % 4);
    }
}

fn main() -> Result<()> {
    let args = Args::parse();

    let mut app = App::new(args.path)?;

    // setup terminal
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen, EnableMouseCapture)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    // run app
    let res = run_app(&mut terminal, &mut app);

    // restore terminal
    disable_raw_mode()?;
    execute!(
        terminal.backend_mut(),
        LeaveAlternateScreen,
        DisableMouseCapture
    )?;
    terminal.show_cursor()?;

    if let Err(err) = res {
        println!("{:?}", err)
    }

    Ok(())
}

fn run_app<B: Backend>(terminal: &mut Terminal<B>, app: &mut App) -> io::Result<()> {
    while !app.should_quit {
        terminal.draw(|f| ui(f, app))?;

        if event::poll(std::time::Duration::from_millis(100))? {
            if let Event::Key(key) = event::read()? {
                match key.code {
                    KeyCode::Char('q') | KeyCode::Char('Q') => app.should_quit = true,
                    KeyCode::Tab => app.next_tab(),
                    KeyCode::Down => {
                        if app.selected_row < app.num_rows.saturating_sub(1) {
                            app.selected_row += 1;
                        }
                    }
                    KeyCode::Up => {
                        if app.selected_row > 0 {
                            app.selected_row -= 1;
                        }
                    }
                    KeyCode::Right => {
                        if app.col_offset < app.num_cols.saturating_sub(1) {
                            app.col_offset += 1;
                        }
                    }
                    KeyCode::Left => {
                        if app.col_offset > 0 {
                            app.col_offset -= 1;
                        }
                    }
                    _ => {}
                }
            }
        }
    }
    Ok(())
}

fn ui(f: &mut Frame, app: &App) {
    let size = f.size();
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(3),
            Constraint::Min(0),
            Constraint::Length(1),
        ])
        .split(size);

    // Tab bar
    let tab_block = Block::default().borders(Borders::ALL);
    let tab_rect = chunks[0];

    let titles = Tab::names().into_iter().enumerate().map(|(i, name)| {
        if Tab::from_index(i) == app.active_tab {
            format!(" {} ", name)
        } else {
            format!(" {} ", name)
        }
    }).collect::<Vec<_>>();

    let tabs = Tabs::new(titles)
        .block(tab_block)
        .select(app.active_tab.to_index())
        .highlight_style(Style::default().add_modifier(Modifier::REVERSED))
        .divider("");

    f.render_widget(tabs, tab_rect);

    // Path on the right of tabs
    let path_str = app.path.to_string_lossy();
    let path_para = Paragraph::new(path_str.as_ref())
        .alignment(Alignment::Right)
        .block(Block::default().padding(ratatui::widgets::Padding::horizontal(1)));

    let mut path_rect = tab_rect;
    path_rect.y += 1;
    path_rect.height = 1;
    f.render_widget(path_para, path_rect);

    match app.active_tab {
        Tab::Visualize => render_visualize(f, chunks[1], app),
        Tab::Metadata => render_metadata(f, chunks[1], app),
        Tab::Schema => render_schema(f, chunks[1], app),
        Tab::RowGroups => render_row_groups(f, chunks[1], app),
    }

    let footer_text = match app.active_tab {
        Tab::Visualize => "parqeye           ↑/↓ : Row | →/← : Column | u/d : Page - [Tab] Next Tab, [Q]uit",
        Tab::Metadata => "parqeye                                                   [Tab] Next Tab, [Q]uit",
        Tab::Schema => "parqeye                      ←/→ : Scroll, ↑/↓ : Schema - [Tab] Next Tab, [Q]uit",
        Tab::RowGroups => "parqeye          →/← : Iterate Row Groups, ↑/↓ : Schema - [Tab] Next Tab, [Q]uit",
    };
    let footer = Paragraph::new(footer_text);
    f.render_widget(footer, chunks[2]);
}

fn render_visualize(f: &mut Frame, area: Rect, app: &App) {
    // Basic implementation for now
    let paragraph = Paragraph::new("Visualize Content (Table Implementation Pending)");
    f.render_widget(paragraph, area);
}

fn render_metadata(f: &mut Frame, area: Rect, app: &App) {
    let metadata = app.file_reader.metadata();
    let file_metadata = metadata.file_metadata();

    let format_version = file_metadata.version();
    let created_by = file_metadata.created_by().unwrap_or("unknown");
    let rows = file_metadata.num_rows();
    let cols = file_metadata.schema().num_columns();
    let row_groups = metadata.num_row_groups();

    // Calculate sizes
    let mut raw_size = 0;
    let mut compressed_size = 0;
    for i in 0..row_groups {
        let rg = metadata.row_group(i);
        raw_size += rg.total_byte_size();
        // compressed size is sum of column chunk compressed sizes
        for j in 0..rg.num_columns() {
            compressed_size += rg.column(j).compressed_size();
        }
    }

    let compression_ratio = if compressed_size > 0 {
        raw_size as f64 / compressed_size as f64
    } else {
        1.0
    };

    let metadata_text = format!(
        "    Format version {}\n\
             Created by {}\n\
                   Rows {}\n\
                Columns {}\n\
             Row groups {}\n\
             Size (raw) {}\n\
      Size (compressed) {}\n\
      Compression ratio {:.2}x\n\
          Codecs (cols) UNCOMPRESSED({})\n\
              Encodings PLAIN, RLE\n\
           Avg row size {} B",
        format_version,
        created_by,
        rows,
        cols,
        row_groups,
        format_size(raw_size),
        format_size(compressed_size),
        compression_ratio,
        cols,
        if rows > 0 { raw_size / rows } else { 0 }
    );

    let block = Block::default()
        .title("File Metadata")
        .borders(Borders::ALL)
        .title_alignment(Alignment::Center);

    // Center the metadata block
    let metadata_chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(5),
            Constraint::Length(13),
            Constraint::Min(0),
        ])
        .split(area);

    let metadata_horiz = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Min(0),
            Constraint::Length(80),
            Constraint::Min(0),
        ])
        .split(metadata_chunks[1]);

    let paragraph = Paragraph::new(metadata_text).block(block);
    f.render_widget(paragraph, metadata_horiz[1]);
}

fn format_size(bytes: i64) -> String {
    if bytes < 1024 {
        format!("{} B", bytes)
    } else if bytes < 1024 * 1024 {
        format!("{:.2} KiB", bytes as f64 / 1024.0)
    } else {
        format!("{:.2} MiB", bytes as f64 / (1024.0 * 1024.0))
    }
}

fn render_schema(f: &mut Frame, area: Rect, app: &App) {
    let paragraph = Paragraph::new("Schema Content");
    f.render_widget(paragraph, area);
}

fn render_row_groups(f: &mut Frame, area: Rect, app: &App) {
    let paragraph = Paragraph::new("Row Groups Content");
    f.render_widget(paragraph, area);
}
EOF
"}

