use parquet::schema::types::Type;
use std::sync::Arc;

#[derive(Parser)]
#[command(author, version, about, long_about = None)]
struct Args {
    #[arg(help = "Path to the parquet file")]
    path: PathBuf,
}

#[derive(Clone, Copy, PartialEq)]
enum Tab {
    Visualize,
    Metadata,
    Schema,
    RowGroups,
}

impl Tab {
    fn from_index(index: usize) -> Self {
        match index {
            0 => Tab::Visualize,
            1 => Tab::Metadata,
            2 => Tab::Schema,
            3 => Tab::RowGroups,
            _ => Tab::Visualize,
        }
    }

    fn to_index(&self) -> usize {
        match self {
            Tab::Visualize => 0,
            Tab::Metadata => 1,
            Tab::Schema => 2,
            Tab::RowGroups => 3,
        }
    }

    fn names() -> Vec<&'static str> {
        vec!["Visualize", "Metadata", "Schema", "Row Groups"]
    }
}

struct App {
    path: PathBuf,
    active_tab: Tab,
    should_quit: bool,

    // Parquet data
    file_reader: Arc<SerializedFileReader<File>>,
    num_rows: usize,
    num_cols: usize,
    num_row_groups: usize,

    // Visualize state
    row_offset: usize,
    col_offset: usize,
    selected_row: usize,
}

impl App {
    fn new(path: PathBuf) -> Result<Self> {
        let file = File::open(&path)?;
        let file_reader = Arc::new(SerializedFileReader::new(file)?);
        let metadata = file_reader.metadata();
        let num_rows = metadata.file_metadata().num_rows() as usize;
        let num_cols = metadata.file_metadata().schema().num_columns();
        let num_row_groups = metadata.num_row_groups();

        Ok(Self {
            path,
            active_tab: Tab::Visualize,
            should_quit: false,
            file_reader,
