    let metadata = app.file_reader.metadata();
    let file_metadata = metadata.file_metadata();

    let format_version = file_metadata.version();
    let created_by = file_metadata.created_by().unwrap_or("unknown");
    let rows = file_metadata.num_rows();
    let cols = file_metadata.schema().num_columns();
    let row_groups = metadata.num_row_groups();

    // Calculate sizes
    let mut raw_size = 0;
    let mut compressed_size = 0;
    for i in 0..row_groups {
        let rg = metadata.row_group(i);
        raw_size += rg.total_byte_size();
        // compressed size is sum of column chunk compressed sizes
        for j in 0..rg.num_columns() {
            compressed_size += rg.column(j).compressed_size();
        }
    }

    let compression_ratio = if compressed_size > 0 {
        raw_size as f64 / compressed_size as f64
    } else {
        1.0
    };

    let metadata_text = format!(
        "    Format version {}\n\
             Created by {}\n\
                   Rows {}\n\
                Columns {}\n\
             Row groups {}\n\
             Size (raw) {}\n\
      Size (compressed) {}\n\
      Compression ratio {:.2}x\n\
          Codecs (cols) UNCOMPRESSED({})\n\
