        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Min(0),
            Constraint::Length(80),
            Constraint::Min(0),
        ])
        .split(metadata_chunks[1]);

    let paragraph = Paragraph::new(metadata_text).block(block);
    f.render_widget(paragraph, metadata_horiz[1]);
}

fn format_size(bytes: i64) -> String {
    if bytes < 1024 {
        format!("{} B", bytes)
    } else if bytes < 1024 * 1024 {
        format!("{:.2} KiB", bytes as f64 / 1024.0)
    } else {
        format!("{:.2} MiB", bytes as f64 / (1024.0 * 1024.0))
    }
}

fn render_schema(f: &mut Frame, area: Rect, app: &App) {
    let paragraph = Paragraph::new("Schema Content");
    f.render_widget(paragraph, area);
}

fn render_row_groups(f: &mut Frame, area: Rect, app: &App) {
    let paragraph = Paragraph::new("Row Groups Content");
    f.render_widget(paragraph, area);
}
