    fn calculate_col_widths(&mut self) {
        let metadata = self.file_reader.metadata();
        let schema = metadata.file_metadata().schema();
        for i in 0..self.num_cols {
            let name = schema.column(i).name();
            let mut max_w = name.len();
            // Check first few rows for width
            for row in self.cached_rows.iter().take(20) {
                let val = format_field(row.get_column_iter().nth(i).unwrap().1);
                max_w = max_w.max(val.len());
            }
            self.col_widths[i] = (max_w as u16 + 2).max(10);
        }
    }

    fn update_cache(&mut self, start: usize) {
        if !self.cached_rows.is_empty() && start >= self.cache_start && start + 50 <= self.cache_start + self.cached_rows.len() {
             return;
        }
        let limit = 100;
        let mut iter = self.file_reader.get_row_iter(None).unwrap();
        self.cached_rows = iter.nth(start).into_iter().chain(iter.take(limit - 1)).collect();
