#[derive(Clone, Copy, PartialEq, Debug)]
enum Tab {
    Visualize,
    Metadata,
    Schema,
    RowGroups,
}

impl Tab {
    fn from_index(index: usize) -> Self {
        match index {
            0 => Tab::Visualize,
            1 => Tab::Metadata,
            2 => Tab::Schema,
            3 => Tab::RowGroups,
            _ => Tab::Visualize,
        }
    }

    fn to_index(&self) -> usize {
