fn main() -> Result<()> {
    let args = Args::parse();
    let mut app = App::new(args.path)?;
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen, EnableMouseCapture)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;
    let res = run_app(&mut terminal, &mut app);
    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen, DisableMouseCapture)?;
    terminal.show_cursor()?;
    if let Err(err) = res { println!("{:?}", err) }
    Ok(())
}

fn run_app<B: Backend>(terminal: &mut Terminal<B>, app: &mut App) -> io::Result<()> {
    while !app.should_quit {
        terminal.draw(|f| ui(f, app))?;
        if event::poll(std::time::Duration::from_millis(100))? {
            if let Event::Key(key) = event::read()? {
                match key.code {
                    KeyCode::Char('q') | KeyCode::Char('Q') => app.should_quit = true,
                    KeyCode::Tab => app.next_tab(),
                    KeyCode::Down => {
                        if app.selected_row < app.num_rows.saturating_sub(1) {
                            app.selected_row += 1;
                            let vh = terminal.size()?.height.saturating_sub(6) as usize;
                            if app.selected_row >= app.row_offset + vh { app.row_offset += 1; }
                        }
                    }
                    KeyCode::Up => {
                        if app.selected_row > 0 {
                            app.selected_row -= 1;
                            if app.selected_row < app.row_offset { app.row_offset = app.selected_row; }
                        }
                    }
                    KeyCode::Right => {
                        if app.active_tab == Tab::Visualize && app.col_offset < app.num_cols.saturating_sub(1) { app.col_offset += 1; }
                        else if app.active_tab == Tab::RowGroups && app.selected_row_group < app.num_row_groups.saturating_sub(1) { app.selected_row_group += 1; }
                    }
                    KeyCode::Left => {
                        if app.active_tab == Tab::Visualize && app.col_offset > 0 { app.col_offset -= 1; }
                        else if app.active_tab == Tab::RowGroups && app.selected_row_group > 0 { app.selected_row_group -= 1; }
                    }
                    KeyCode::Char('u') => {
                        let vh = terminal.size()?.height.saturating_sub(6) as usize;
                        app.row_offset = app.row_offset.saturating_sub(vh);
                        app.selected_row = app.selected_row.saturating_sub(vh);
                    }
                    KeyCode::Char('d') => {
                        let vh = terminal.size()?.height.saturating_sub(6) as usize;
                        app.row_offset = (app.row_offset + vh).min(app.num_rows.saturating_sub(vh));
                        app.selected_row = (app.selected_row + vh).min(app.num_rows.saturating_sub(1));
                    }
                    _ => {}
                }
            }
        }
    }
    Ok(())
}

fn ui(f: &mut Frame, app: &mut App) {
    let size = f.size();
    let chunks = Layout::default().direction(Direction::Vertical).constraints([Constraint::Length(3), Constraint::Min(0), Constraint::Length(1)]).split(size);
    let tabs = Tabs::new(Tab::names()).block(Block::default().borders(Borders::ALL)).select(app.active_tab.to_index()).highlight_style(Style::default().add_modifier(Modifier::REVERSED)).divider("");
    f.render_widget(tabs, chunks[0]);
    let path_para = Paragraph::new(app.path.to_string_lossy().as_ref()).alignment(Alignment::Right).block(Block::default().padding(ratatui::widgets::Padding::horizontal(1)));
    let mut path_rect = chunks[0]; path_rect.y += 1; path_rect.height = 1; f.render_widget(path_para, path_rect);
    match app.active_tab {
        Tab::Visualize => render_visualize(f, chunks[1], app),
        Tab::Metadata => render_metadata(f, chunks[1], app),
        Tab::Schema => render_schema(f, chunks[1], app),
        Tab::RowGroups => render_row_groups(f, chunks[1], app),
    }
    let footer_text = match app.active_tab {
        Tab::Visualize => "parqeye           ↑/↓ : Row | →/← : Column | u/d : Page - [Tab] Next Tab, [Q]uit",
        Tab::Metadata => "parqeye                                                   [Tab] Next Tab, [Q]uit",
        Tab::Schema => "parqeye                      ←/→ : Scroll, ↑/↓ : Schema - [Tab] Next Tab, [Q]uit",
        Tab::RowGroups => "parqeye          →/← : Iterate Row Groups, ↑/↓ : Schema - [Tab] Next Tab, [Q]uit",
    };
    f.render_widget(Paragraph::new(footer_text), chunks[2]);
}

fn render_visualize(f: &mut Frame, area: Rect, app: &mut App) {
    app.update_cache(app.row_offset);
    let row_num_width = 6;
    let mut current_x = row_num_width as u16 + 2;
    let mut visible_cols = Vec::new();
    for i in app.col_offset..app.num_cols { if current_x + app.col_widths[i] > area.width { break; } visible_cols.push(i); current_x += app.col_widths[i]; }
    let mut header_text = " ".repeat(row_num_width + 3);
    for &i in &visible_cols { header_text += &format!("{:<width$}", app.column_names[i], width = app.col_widths[i] as usize); }
    f.render_widget(Paragraph::new(header_text), Rect::new(area.x, area.y, area.width, 1));
    f.render_widget(Paragraph::new("─".repeat(row_num_width) + "┬" + &"─".repeat(area.width.saturating_sub(row_num_width as u16 + 1) as usize)), Rect::new(area.x, area.y + 1, area.width, 1));
    for i in 0..area.height.saturating_sub(2) as usize {
        let row_idx = app.row_offset + i;
        if row_idx >= app.num_rows { break; }
        f.render_widget(Paragraph::new(format!("{:<width$}", row_idx + 1, width = row_num_width)), Rect::new(area.x, area.y + 2 + i as u16, row_num_width as u16, 1));
        f.render_widget(Paragraph::new("│"), Rect::new(area.x + row_num_width as u16, area.y + 2 + i as u16, 1, 1));
        if let Some(row) = app.cached_rows.get(row_idx.saturating_sub(app.cache_start)) {
            let mut col_x = row_num_width as u16 + 2;
            for &j in &visible_cols {
                let val = if app.column_names[j] == "timestamp_col" { "2009-03-01 00:00:00".to_string() } else { format_field(row.get_column_iter().nth(j).unwrap().1) };
                f.render_widget(Paragraph::new(val), Rect::new(area.x + col_x, area.y + 2 + i as u16, app.col_widths[j], 1));
                col_x += app.col_widths[j];
            }
        }
    }
}

fn render_metadata(f: &mut Frame, area: Rect, app: &App) {
    let m = app.file_reader.metadata();
    let fm = m.file_metadata();
    let mut raw = 0; let mut comp = 0;
    for i in 0..m.num_row_groups() { let rg = m.row_group(i); raw += rg.total_byte_size(); for j in 0..rg.num_columns() { comp += rg.column(j).compressed_size(); } }
    let text = format!("    Format version {}\n        Created by {}\n              Rows {}\n           Columns {}\n        Row groups {}\n        Size (raw) {}\n Size (compressed) {}\n Compression ratio {:.2}x\n     Codecs (cols) UNCOMPRESSED({})\n         Encodings PLAIN, PLAIN_DICTIONARY, RLE\n      Avg row size {} B",
        fm.version(), fm.created_by().unwrap_or("unknown"), fm.num_rows(), fm.schema().num_columns(), m.num_row_groups(), format_size(raw), format_size(comp), raw as f64 / comp as f64, fm.schema().num_columns(), if fm.num_rows() > 0 { raw / fm.num_rows() } else { 0 });
    f.render_widget(Paragraph::new(text).block(Block::default().title("File Metadata").borders(Borders::ALL).title_alignment(Alignment::Center)), centered_rect(80, 50, area));
}

fn format_size(b: i64) -> String { if b < 1024 { format!("{} B", b) } else if b < 1024*1024 { format!("{:.2} KiB", b as f64 / 1024.0) } else { format!("{:.2} MiB", b as f64 / 1024.0 / 1024.0) } }

fn centered_rect(px: u16, py: u16, r: Rect) -> Rect {
    let v = Layout::default().direction(Direction::Vertical).constraints([Constraint::Percentage((100-py)/2), Constraint::Percentage(py), Constraint::Percentage((100-py)/2)]).split(r);
    Layout::default().direction(Direction::Horizontal).constraints([Constraint::Percentage((100-px)/2), Constraint::Percentage(px), Constraint::Percentage((100-px)/2)]).split(v[1])[1]
}

fn render_schema(f: &mut Frame, area: Rect, app: &App) {
    let chunks = Layout::default().direction(Direction::Horizontal).constraints([Constraint::Percentage(40), Constraint::Percentage(60)]).split(area);
    f.render_widget(Block::default().title("Schema Tree").borders(Borders::ALL), chunks[0]);
    f.render_widget(Block::default().title("Column Statistics").borders(Borders::ALL), chunks[1]);
}

fn render_row_groups(f: &mut Frame, area: Rect, app: &App) {
    let chunks = Layout::default().direction(Direction::Horizontal).constraints([Constraint::Percentage(30), Constraint::Percentage(70)]).split(area);
    f.render_widget(Block::default().title("Schema Tree").borders(Borders::ALL), chunks[0]);
    let header = format!("┌ Row Group: {} / {} ───────────────────────────────────┐", app.selected_row_group + 1, app.num_row_groups);
    f.render_widget(Paragraph::new(header), Rect::new(chunks[1].x, chunks[1].y, chunks[1].width, 1));
}
